1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.mapstruct.Named;
7	import org.springframework.data.domain.Page;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
12	
13	import java.util.Collection;
14	import java.util.List;
15	
16	/**
17	 * Maps Owner & OwnerDto using Mapstruct
18	 */
19	@Mapper(uses = PetMapper.class)
20	public interface OwnerMapper {
21	
22	    OwnerDto toOwnerDto(Owner owner);
23	
24	    Owner toOwner(OwnerDto ownerDto);
25	
26	    @Mapping(target = "id", ignore = true)
27	    @Mapping(target = "pets", ignore = true)
28	    @Mapping(target = "telephone", source = "telephone", qualifiedByName = "normalizeTelephone")
29	    Owner toOwner(OwnerFieldsDto ownerDto);
30	
31	    /** Strip every non-digit character so the create path stores the bare 10-digit telephone. */
32	    @Named("normalizeTelephone")
33	    default String normalizeTelephone(String telephone) {
34	        return telephone == null ? null : telephone.replaceAll("\\D", "");
35	    }
36	
37	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
38	
39	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
40	
41	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
42	        OwnerPageDto ownerPageDto = new OwnerPageDto();
43	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
44	        ownerPageDto.setPage(ownerPage.getNumber());
45	        ownerPageDto.setSize(ownerPage.getSize());
46	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
47	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
48	        return ownerPageDto;
49	    }
50	}
